// Функція для створення розмітки галереї (під шаблон SimpleLightbox)
function createGalleryMarkup(images) {
  return images.map(({ preview, original, description }) => `
    <li class="gallery-item">
      <a class="gallery-link" href="${original}">
        <img
          class="gallery-image"
          src="${preview}"
          alt="${description}"
        />
      </a>
    </li>
  `).join('');
}

// Вставка галереї в DOM
const gallery = document.querySelector('.gallery');
gallery.innerHTML = createGalleryMarkup(images);

// Ініціалізація SimpleLightbox
new SimpleLightbox('.gallery .gallery-link', {
  captions: true,        // відображає підписи
  captionsData: 'alt',   // бере підпис з атрибута alt
  captionDelay: 250      // затримка появи підпису 250 мс
});


